// Augment the generated Worksheet class with JS-side methods
declare module './generated' {
  interface Workbook {
    /** Number of workbook-level data connections. */
    readonly dataConnectionCount: number

    /** Workbook-level data connection names. */
    readonly dataConnectionNames: string[]

    /** Workbook-level data connection definitions. */
    readonly dataConnections: JsWorkbookConnectionDefinition[]

    /** Number of raw workbook extension elements preserved from the package. */
    readonly workbookExtensionCount: number

    /** Raw workbook extension elements preserved from workbook.xml. */
    readonly workbookExtensions: JsWorkbookExtension[]

    /** Number of raw workbook-related extension package parts. */
    readonly workbookExtensionPartCount: number

    /** Raw workbook-related extension package parts. */
    readonly workbookExtensionParts: JsWorkbookExtensionPart[]

    /** Get a raw workbook extension package part by package path. */
    getWorkbookExtensionPart(path: string): JsWorkbookExtensionPart | null

    /** Get a raw workbook extension package part by workbook relationship id. */
    getWorkbookExtensionPartByRelationshipId(relationshipId: string): JsWorkbookExtensionPart | null

    /** Get a workbook-level data connection by name. */
    getDataConnection(name: string): JsWorkbookConnectionDefinition | null

    /** Get a workbook-level data connection by id. */
    getDataConnectionById(id: number): JsWorkbookConnectionDefinition | null

    /** Add a workbook-level database connection. */
    addDataConnection(options: JsWorkbookConnectionOptions): void

    /** Refresh all pivot tables in the workbook. */
    refreshPivots(options?: JsPivotRefreshOptions | null): JsPivotRefreshStats
  }

  interface Worksheet {
    /**
     * Iterate over all rows with data as sparse rows.
     * Only non-empty cells are included. Internally batches FFI calls for performance.
     * When metadata flags are enabled, cells with that metadata are included even if empty.
     */
    iterateRows(opts?: JsRowsOptions): RowIterator

    /** Number of pivot tables on the worksheet. */
    readonly pivotCount: number

    /** Pivot table names on the worksheet. */
    readonly pivotTableNames: string[]

    /** Pivot table definitions on the worksheet. */
    readonly pivotTables: JsPivotTableDefinition[]

    /** Get a pivot table definition by name. */
    getPivotTable(name: string): JsPivotTableDefinition | null

    /** Add a semantic pivot table definition to the worksheet. */
    addPivotTable(options: JsPivotTableOptions): void

    /** Generate and add a PivotChart from a rendered pivot table. */
    addPivotChart(options: JsPivotChartOptions): JsChart
  }
}

export type JsChart = Omit<Generated.JsChart, 'anchor'>
export type JsChartSheet = Omit<Generated.JsChartSheet, 'chart'> & { chart: JsChart }

export interface DrawingMeta {
  name?: string
  hidden: boolean
  locked: boolean
  printable: boolean
  altText?: string
  title?: string
}

export interface DrawingMetaInput {
  name?: string
  hidden?: boolean
  locked?: boolean
  printable?: boolean
  altText?: string
  title?: string
}

/** A cell-relative anchor marker. Offsets are EMU within the cell and always present on output. */
export interface DrawingCellMarker {
  col: number
  row: number
  colOffsetEmu?: number
  rowOffsetEmu?: number
}

/** Anchor spanning two cell markers; `editAs` records the sizing behavior Excel applies on edit. */
export interface TwoCellAnchor {
  type: 'twoCell'
  from: DrawingCellMarker
  to: DrawingCellMarker
  editAs?: 'twoCell' | 'oneCell' | 'absolute'
}

/** Anchor pinned to one cell with a fixed EMU extent. */
export interface OneCellAnchor {
  type: 'oneCell'
  from: DrawingCellMarker
  widthEmu: number
  heightEmu: number
}

/** Anchor at a fixed EMU position and extent, independent of cells. */
export interface AbsoluteAnchor {
  type: 'absolute'
  xEmu: number
  yEmu: number
  widthEmu: number
  heightEmu: number
}

/** Drawing anchors preserve their file variant on read and accept any variant on write. */
export type DrawingAnchor = TwoCellAnchor | OneCellAnchor | AbsoluteAnchor

export interface DrawingChildTransform {
  xEmu?: number
  yEmu?: number
  cxEmu?: number
  cyEmu?: number
  rotation?: number
  flipH?: boolean
  flipV?: boolean
}

export interface DrawingGroupTransform extends DrawingChildTransform {
  childXEmu?: number
  childYEmu?: number
  childCxEmu?: number
  childCyEmu?: number
}

export type DrawingPlacement =
  | { anchor: DrawingAnchor; transform?: never }
  | { anchor?: never; transform: DrawingChildTransform }

export type DrawingColor =
  | { colorType: 'auto' }
  | { colorType: 'rgb'; r: number; g: number; b: number }
  | { colorType: 'argb'; a: number; r: number; g: number; b: number }
  | { colorType: 'theme'; index: number; tint: number }
  | { colorType: 'indexed'; index: number }

export interface DrawingRunFont {
  bold?: boolean
  italic?: boolean
  size?: number
  color?: DrawingColor
  name?: string
  underline?: 'none' | 'single' | 'double' | 'singleAccounting' | 'doubleAccounting'
  strikethrough?: boolean
  verticalAlign?: 'baseline' | 'superscript' | 'subscript'
  family?: number
  charset?: number
  scheme?: string
}

export interface DrawingText {
  runs: Array<{ text: string; font?: DrawingRunFont }>
  horizontalAlignment?: 'general' | 'left' | 'center' | 'right' | 'fill' | 'justify' | 'centerContinuous' | 'distributed'
  verticalAlignment?: 'top' | 'center' | 'bottom' | 'justify' | 'distributed'
}

export type FormControlKind =
  | { kind: 'button'; caption: DrawingText }
  | { kind: 'checkbox'; caption: DrawingText; state: 'unchecked' | 'checked' | 'mixed'; cellLink?: string; no3D: boolean }
  /**
   * `firstInGroup` reports whether this radio heads its group; writers
   * recompute it from group-box containment, so it is read-side
   * information. `'mixed'` never validates on write but can surface
   * when reading hostile files.
   */
  | { kind: 'optionButton'; caption: DrawingText; state: 'unchecked' | 'checked' | 'mixed'; cellLink?: string; firstInGroup: boolean; no3D: boolean }
  | { kind: 'label'; caption: DrawingText }
  | { kind: 'groupBox'; caption: DrawingText; no3D: boolean }
  | { kind: 'listBox'; inputRange?: string; cellLink?: string; selection: 'single' | 'multi' | 'extend'; selected: number[]; no3D: boolean }
  | { kind: 'dropdown'; inputRange?: string; cellLink?: string; selected?: number; lines: number; no3D: boolean }
  | { kind: 'scrollbar'; value: number; min: number; max: number; increment: number; page: number; horizontal: boolean; cellLink?: string }
  | { kind: 'spinner'; value: number; min: number; max: number; increment: number; cellLink?: string }
  /** Unsupported legacy control, preserved for passthrough. */
  | { kind: 'unknown'; objectType: string; legacyObjectType?: number; caption: DrawingText }

export type FormControlKindInput =
  | { kind: 'button'; caption: DrawingText }
  | { kind: 'checkbox'; caption: DrawingText; state: 'unchecked' | 'checked' | 'mixed'; cellLink?: string; no3D?: boolean }
  /** `firstInGroup` is ignored on input; writers recompute it from group-box containment. */
  | { kind: 'optionButton'; caption: DrawingText; state: 'unchecked' | 'checked'; cellLink?: string; firstInGroup?: boolean; no3D?: boolean }
  | { kind: 'label'; caption: DrawingText }
  | { kind: 'groupBox'; caption: DrawingText; no3D?: boolean }
  | { kind: 'listBox'; inputRange?: string; cellLink?: string; selection: 'single' | 'multi' | 'extend'; selected?: number[]; no3D?: boolean }
  | { kind: 'dropdown'; inputRange?: string; cellLink?: string; selected?: number; lines: number; no3D?: boolean }
  | { kind: 'scrollbar'; value: number; min: number; max: number; increment: number; page: number; horizontal?: boolean; cellLink?: string }
  | { kind: 'spinner'; value: number; min: number; max: number; increment: number; cellLink?: string }
  | { kind: 'unknown'; objectType: string; legacyObjectType?: number; caption?: DrawingText }

export interface FormControlPayload {
  kind: FormControlKind
  macroName?: string
  /**
   * Unmodeled VML ClientData child fragments preserved on any control
   * kind (`<x:Disabled/>`, button dialog semantics, ...); opaque
   * internal passthrough echoed back unchanged on write.
   */
  rawClientData: Buffer[]
  /**
   * Unmodeled XLSX formControlPr attributes preserved on any control
   * kind; opaque internal passthrough echoed back unchanged on write.
   */
  rawProperties: Array<[string, string]>
  /** Original BIFF OBJ body for XLS passthrough of unknown controls. */
  rawObj?: Buffer
}

export interface FormControlInputPayload {
  kind: FormControlKindInput
  macroName?: string
  /** Echo back the raw* fields unchanged when rewriting a control read from a file. */
  rawClientData?: Buffer[]
  rawProperties?: Array<[string, string]>
  rawObj?: Buffer
}

